                + "<ac:adf-extension>"
                + "<ac:adf-node type=\"bodied-sync-block\">"
                + "<ac:adf-attribute key=\"resource-id\">fedb2b81-0000</ac:adf-attribute>"
                + "<ac:adf-attribute key=\"local-id\">08922e0e-0000</ac:adf-attribute>"
                + "<ac:adf-content>"
                + innerContent
                + "</ac:adf-content>"
                + "</ac:adf-node>"
                + "</ac:adf-extension>";
    }

    @Test
    public void syncedBlockParagraphContentIsConvertedInline() {
        String md = ConfluenceStorageMarkdown.toMarkdown(
                syncBlock("<p>Mahler responds with the upload pre-signed URLs</p>"));

        assertTrue("synced block paragraph must survive conversion",
                md.contains("Mahler responds with the upload pre-signed URLs"));
        assertFalse("synced block must NOT be replaced by the [Diagram] placeholder",
                md.contains("Diagram"));
    }

    @Test
    public void syncedBlockCodeMacroContentIsPreserved() {
        String md = ConfluenceStorageMarkdown.toMarkdown(
                syncBlock("<ac:structured-macro ac:name=\"code\" ac:schema-version=\"1\">"
                        + "<ac:plain-text-body><![CDATA[{\"payload\": {\"request_id\": \"abc\"}}]]></ac:plain-text-body>"
                        + "</ac:structured-macro>"));

        assertTrue("code macro body inside a synced block must survive",
                md.contains("request_id"));
        assertFalse("synced block must NOT be replaced by the [Diagram] placeholder",
                md.contains("Diagram"));
    }

    @Test
    public void realDrawioExtensionStillBecomesDiagramPlaceholder() {
        // Control: a real draw.io / ecosystem extension (type="extension", no
        // readable content) must keep mapping to the [Diagram] placeholder.
        String md = ConfluenceStorageMarkdown.toMarkdown(
                "<ac:adf-extension>"
                        + "<ac:adf-node type=\"extension\">"
                        + "<ac:adf-attribute key=\"extension-key\">drawio</ac:adf-attribute>"
                        + "</ac:adf-node>"
                        + "</ac:adf-extension>");

        assertTrue("draw.io extension keeps the [Diagram] placeholder",
                md.contains("Diagram"));
    }
}

 * <p>Handled Confluence constructs:
 * <ul>
 *   <li>{@code <ac:image><ri:attachment ri:filename="..."/></ac:image>}
 *       → {@code ![filename](filename)}</li>
 *   <li>{@code <ac:link><ri:page ri:content-title="..."/><ac:link-body>text</ac:link-body></ac:link>}
 *       → {@code [text](title)}</li>
 *   <li>{@code <ac:link><ri:attachment ri:filename="..."/>...}</ac:link>}
 *       → {@code [text](filename)}</li>
 *   <li>{@code <ac:link><ri:url ri:value="..."/>...}</ac:link>}
 *       → {@code [text](url)}</li>
 *   <li>{@code <ac:plain-text-link-body>} → plain text link body preserved</li>
 *   <li>{@code <ac:task>} with status + body → {@code - [ ] body} / {@code - [x] body}</li>
 *   <li>{@code <ac:adf-node type="extension">} (e.g. draw.io)
 *       → {@code [Diagram]}</li>
 *   <li>{@code <ac:structured-macro ac:name="toc">} → removed (auto-generated noise)</li>
 *   <li>{@code <table>} → GitHub-Flavoured Markdown table</li>
 * </ul>
 */
public final class ConfluenceStorageMarkdown {

    private static final Logger logger = LogManager.getLogger(ConfluenceStorageMarkdown.class);

    // ac:image → img: <ac:image ... ac:alt="name.png" ...><ri:attachment .../></ac:image>
    private static final Pattern AC_IMAGE = Pattern.compile(
        "<ac:image[^>]*>\\s*<ri:attachment\\s+ri:filename=\"([^\"]+)\"[^/]*/?>\\s*</ac:image>",
        Pattern.DOTALL | Pattern.CASE_INSENSITIVE
    );

    // ac:image without alt — fall back to ri:filename
    private static final Pattern AC_IMAGE_ALT = Pattern.compile(
        "ac:alt=\"([^\"]+)\"",
        Pattern.CASE_INSENSITIVE
    );

    // ac:link with ri:page title and optional ac:link-body text
    private static final Pattern AC_LINK = Pattern.compile(
        "<ac:link[^>]*>\\s*<ri:page\\s+ri:content-title=\"([^\"]+)\"[^/]*/?>\\s*(?:<ac:link-body>(.*?)</ac:link-body>)?\\s*</ac:link>",
        Pattern.DOTALL | Pattern.CASE_INSENSITIVE
    );

    // ac:task-list wrapper — just unwrap it
    private static final Pattern AC_TASK_LIST = Pattern.compile(
        "<ac:task-list>(.*?)</ac:task-list>",
        Pattern.DOTALL | Pattern.CASE_INSENSITIVE
    );

    // individual ac:task
    private static final Pattern AC_TASK = Pattern.compile(
        "<ac:task>.*?<ac:task-status>(.*?)</ac:task-status>.*?<ac:task-body>(.*?)</ac:task-body>.*?</ac:task>",
        Pattern.DOTALL | Pattern.CASE_INSENSITIVE
    );

    // ac:adf-node (draw.io / ecosystem extensions)
    private static final Pattern AC_ADF_NODE = Pattern.compile(
        "<ac:adf-node[^>]*>.*?</ac:adf-node>",
        Pattern.DOTALL | Pattern.CASE_INSENSITIVE
    );

    // ac:adf-node type="bodied-sync-block" (synced block) — carries real content
    // inline in <ac:adf-content>; must be unwrapped, not dropped (dm.ai #596).
    private static final Pattern AC_ADF_SYNC_BLOCK = Pattern.compile(
        "<ac:adf-node\\b[^>]*type=\"bodied-sync-block\"[^>]*>(.*?)</ac:adf-node>",
        Pattern.DOTALL | Pattern.CASE_INSENSITIVE
    );

    // inner payload of a synced block
    private static final Pattern AC_ADF_CONTENT = Pattern.compile(
        "<ac:adf-content[^>]*>(.*?)</ac:adf-content>",
        Pattern.DOTALL | Pattern.CASE_INSENSITIVE
    );

    // ac:structured-macro name="toc" (table of contents — auto-generated, noise)
    private static final Pattern AC_TOC = Pattern.compile(
        "<ac:structured-macro\\s+ac:name=\"toc\"[^>]*/?>",
        Pattern.DOTALL | Pattern.CASE_INSENSITIVE
    );

    private ConfluenceStorageMarkdown() {}

