public class ConfluenceSyncedBlockMarkdownTest {

    private static String syncBlock(String innerContent) {
        return "<h2>2. Get pre-signed URLs</h2>"
                + "<ac:adf-extension>"
                + "<ac:adf-node type=\"bodied-sync-block\">"
