                        + "<ac:adf-attribute key=\"extension-key\">drawio</ac:adf-attribute>"
                        + "</ac:adf-node>"
                        + "</ac:adf-extension>");

        assertTrue("draw.io extension keeps the [Diagram] placeholder",
                md.contains("Diagram"));
    }
