      final md = confluenceStorageToMarkdown(
        '<ac:adf-extension>'
        '<ac:adf-node type="extension">'
        '<ac:adf-attribute key="extension-key">drawio</ac:adf-attribute>'
        '</ac:adf-node>'
        '</ac:adf-extension>',
      );
      expect(md, contains('[Diagram]'));
      expect(md, isNot(contains('drawio')));
