        '<table><tbody><tr><th>A</th></tr><tr><td>1</td></tr></tbody></table>',
      ));
      expect(md, contains('| A |'));
      expect(md, contains('| 1 |'));
      expect(md, isNot(contains('Diagram')));
    });

